package uk.co.froglog.app.widgets;

/**
 * The site's built-in themes as the widgets use them. Generated by scripts/generate-widget-themes.js from
 * frontend/src/styles and utils/themes.js: do not edit by hand. Colours are 0xAARRGGBB, since --input is translucent in some.
 */
final class WidgetThemes {
    private WidgetThemes() {}

    static final class Entry {
        final String id;
        final String label;
        final boolean light;
        final int card, cardForeground, mutedForeground, secondary, secondaryForeground, primary, primaryForeground, background, border, input;

        Entry(String id, String label, boolean light, int card, int cardForeground, int mutedForeground, int secondary, int secondaryForeground, int primary, int primaryForeground, int background, int border, int input) {
            this.id = id;
            this.label = label;
            this.light = light;
            this.card = card;
            this.cardForeground = cardForeground;
            this.mutedForeground = mutedForeground;
            this.secondary = secondary;
            this.secondaryForeground = secondaryForeground;
            this.primary = primary;
            this.primaryForeground = primaryForeground;
            this.background = background;
            this.border = border;
            this.input = input;
        }
    }

    // In the theme picker's order. "dark" is what the widgets were designed in.
    static final Entry[] ALL = {
        new Entry("light", "Light", true, 0xFFFFFFFF, 0xFF0A0A0A, 0xFF737373, 0xFFF5F5F5, 0xFF171717, 0xFF171717, 0xFFFAFAFA, 0xFFFFFFFF, 0xFFE5E5E5, 0xFFE5E5E5),
        new Entry("dark", "Dark", false, 0xFF171717, 0xFFFAFAFA, 0xFFA1A1A1, 0xFF262626, 0xFFFAFAFA, 0xFFE5E5E5, 0xFF171717, 0xFF0A0A0A, 0xFF2E2E2E, 0x26FFFFFF),
        new Entry("oled", "OLED", false, 0xFF000000, 0xFFF5F5F5, 0xFFA3A3A3, 0xFF171717, 0xFFF5F5F5, 0xFFF5F5F5, 0xFF000000, 0xFF000000, 0xFF333333, 0xFF333333),
        new Entry("nier", "NieR:Automata", true, 0xFFF0ECE0, 0xFF49463D, 0xFF6E6B62, 0xFFE4DFD0, 0xFF49463D, 0xFF6E695B, 0xFFFFFFFF, 0xFFDDD8C7, 0xFFCFCBC0, 0xFFCFCBC0),
        new Entry("frogboxd", "Frogboxd", false, 0xFF1C2228, 0xFFFFFFFF, 0xFF99AABB, 0xFF2C3440, 0xFFFFFFFF, 0xFF00AC1C, 0xFFFFFFFF, 0xFF14181C, 0xFF303840, 0xFF303840),
        new Entry("cyberpunk-2077", "FrogLog 2077", false, 0xFF1C1119, 0xFF5EF6FF, 0xFF9FD8DE, 0xFF2A1720, 0xFF5EF6FF, 0xFFF44638, 0xFFFFFFFF, 0xFF140C15, 0xFF6B2329, 0xFF6B2329),
        new Entry("catppuccin-latte", "Catppuccin Latte", true, 0xFFE6E9EF, 0xFF4C4F69, 0xFF6C6F85, 0xFFDCE0E8, 0xFF4C4F69, 0xFF7287FD, 0xFFFFFFFF, 0xFFEFF1F5, 0xFFC7CAD4, 0xFFC7CAD4),
        new Entry("catppuccin-mocha", "Catppuccin Mocha", false, 0xFF313244, 0xFFCDD6F4, 0xFFA6ADC8, 0xFF45475A, 0xFFCDD6F4, 0xFF7287FD, 0xFFFFFFFF, 0xFF1E1E2E, 0xFF45475A, 0xFF45475A),
        new Entry("rose-pine-dawn", "Rosé Pine Dawn", true, 0xFFFFFAF3, 0xFF575279, 0xFF9893A5, 0xFFF2E9E1, 0xFF575279, 0xFF56949F, 0xFFFFFFFF, 0xFFFAF4ED, 0xFFDDD8DB, 0xFFDDD8DB),
        new Entry("rose-pine", "Rosé Pine", false, 0xFF1F1D2E, 0xFFE0DEF4, 0xFF908CAA, 0xFF26233A, 0xFFE0DEF4, 0xFF31748F, 0xFFFFFFFF, 0xFF191724, 0xFF403D52, 0xFF403D52),
        new Entry("gruvbox-light", "Gruvbox Light", true, 0xFFEBDBB2, 0xFF3C3836, 0xFF7C6F64, 0xFFD5C4A1, 0xFF3C3836, 0xFF458588, 0xFFFFFFFF, 0xFFFBF1C7, 0xFFC8BA99, 0xFFC8BA99),
        new Entry("gruvbox", "Gruvbox", false, 0xFF3C3836, 0xFFEBDBB2, 0xFFD5C4A1, 0xFF504945, 0xFFEBDBB2, 0xFF458588, 0xFFFFFFFF, 0xFF282828, 0xFF665C54, 0xFF665C54),
        new Entry("solarized", "Solarized", true, 0xFFEEE8D5, 0xFF657B83, 0xFF839496, 0xFFD8D2BE, 0xFF657B83, 0xFF268BD2, 0xFFFFFFFF, 0xFFFDF6E3, 0xFFD0D0C2, 0xFFD0D0C2),
        new Entry("nord", "Nord", false, 0xFF3B4252, 0xFFD8DEE9, 0xFFA9AFBC, 0xFF434C5E, 0xFFD8DEE9, 0xFF5E81AC, 0xFFFFFFFF, 0xFF2E3440, 0xFF4C566A, 0xFF4C566A),
        new Entry("terminal", "Terminal", false, 0xFF000000, 0xFF39FF14, 0xFF39FF14, 0xFF0A2E0A, 0xFF39FF14, 0xFF000000, 0xFF39FF14, 0xFF000000, 0xFF0B3304, 0xFF39FF14)
    };

    static Entry find(String id) {
        for (Entry entry : ALL) if (entry.id.equals(id)) return entry;
        return null;
    }
}
